impl<'de> Deserialize<'de> for DiscoverResult {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct Raw {
            result_type: ResultType,
            supported_versions: Vec<ProtocolVersion>,
            capabilities: ServerCapabilities,
            #[serde(default)]
            server_info: Option<Implementation>,
            #[serde(default)]
            instructions: Option<String>,
            ttl_ms: u64,
            cache_scope: CacheScope,
            #[serde(rename = "_meta", default)]
            meta: Option<MetaObject>,
        }
        let raw = Raw::deserialize(deserializer)?;
        let server_info = match raw.server_info {
            Some(info) => info,
            None => {
                let value = raw
                    .meta
                    .as_ref()
                    .and_then(|m| m.get("io.modelcontextprotocol/serverInfo"))
                    .cloned()
                    .ok_or_else(|| {
                        serde::de::Error::missing_field("serverInfo")
                    })?;
                serde_json::from_value(value).map_err(serde::de::Error::custom)?
            }
        };
        Ok(DiscoverResult {
            result_type: raw.result_type,
            supported_versions: raw.supported_versions,
            capabilities: raw.capabilities,
            server_info,
            instructions: raw.instructions,
            ttl_ms: raw.ttl_ms,
            cache_scope: raw.cache_scope,
            meta: raw.meta,
        })
    }
}

